import { Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { SolicitudApoyoModalidadCotizacion } from '../models/solicitud.apoyo.modalidad.cotizacion';

@Injectable({
  providedIn: 'any'
})
export class SolicitudApoyoModalidadCotizacionService extends SuperService<SolicitudApoyoModalidadCotizacion> {
  protected override model: string ="solicitudes_apoyos_mod_cot";
  protected override columns: (keyof SolicitudApoyoModalidadCotizacion)[] = [
    'solicitudes_apoyos_modalidad_id',
    'apoyos_proveedor_id',
    'monto',
    'usuario_id',
    'carta_instruccion_url',
    'spei_url',
    'carta_instruccion_verificacion',
  ];

  constructor(injector: Injector){
    super(injector)
  }

  public async verificarCotizacion(cotizacion: SolicitudApoyoModalidadCotizacion){
        if(!cotizacion) return;
    const fechaVerificacion = cotizacion.carta_instruccion_verificacion? null : new Date().toISOString().replace('T', ' ').split('.')[0]
    const res = await this.update(cotizacion.id, { carta_instruccion_verificacion: fechaVerificacion }, false)
    if(res.status){
      cotizacion.carta_instruccion_verificacion=fechaVerificacion
    }
    return res.status
  }
}